import { renderHook, act } from "@testing-library/react";
import { MemoryRouter, useSearchParams } from "react-router-dom";
import React from "react";
import { afterEach, beforeEach, describe, expect, it, vi, type Mock } from "vitest";
import { useTrackerConnection } from "./useTrackerConnection";
import { initInspectorStore, inspectorStore } from "../store";

const mockLogError = vi.fn();

vi.mock("../InspectorContext", () => ({
  useInspectorContext: () => ({ logError: mockLogError }),
}));

type MockWebSocket = {
  onopen?: () => void;
  onmessage?: (event: { data: string }) => void;
  send: Mock;
  close: Mock;
  url: string;
};

let lastWs: MockWebSocket | undefined;
let wsCtor: Mock;

beforeEach(() => {
  vi.clearAllMocks();
  initInspectorStore();
  lastWs = undefined;
  wsCtor = vi.fn().mockImplementation((url: string) => {
    const ws: MockWebSocket = {
      send: vi.fn(),
      close: vi.fn(),
      url,
    };
    lastWs = ws;
    return ws;
  });
  vi.stubGlobal("WebSocket", wsCtor);
});

afterEach(() => {
  vi.unstubAllGlobals();
});

function renderTrackerHook(
  { enabled, channel }: { enabled: boolean; channel: string },
  initialEntries: string[] = ["/"],
) {
  const wrapper = ({ children }: { children: React.ReactNode }) =>
    React.createElement(MemoryRouter, { initialEntries }, children);
  return renderHook(() => useTrackerConnection({ enabled, channel }), {
    wrapper,
  });
}

function renderWithSearchParamsProbe(initialEntries: string[]) {
  const capturedSearch: { current: string | null } = { current: null };
  const SearchParamsProbe = () => {
    const [searchParams] = useSearchParams();
    React.useEffect(() => {
      capturedSearch.current = searchParams.get("sender");
    }, [searchParams]);
    return null;
  };

  const wrapper = ({ children }: { children: React.ReactNode }) =>
    React.createElement(MemoryRouter, { initialEntries }, [
      React.createElement(SearchParamsProbe, { key: "probe" }),
      children,
    ]);

  const utils = renderHook(() => useTrackerConnection({ enabled: true, channel: "rest" }), {
    wrapper,
  });

  return { capturedSearch, ...utils };
}

describe("useTrackerConnection", () => {
  describe("guards", () => {
    it("does not open a WebSocket when enabled is false", () => {
      act(() => {
        inspectorStore.setState((prev) => ({
          ...prev,
          projectUrl: "http://localhost:5005",
        }));
      });

      renderTrackerHook({ enabled: false, channel: "rest" });

      expect(wsCtor).not.toHaveBeenCalled();
    });

    it("does not open a WebSocket when projectUrl is empty", () => {
      renderTrackerHook({ enabled: true, channel: "rest" });

      expect(wsCtor).not.toHaveBeenCalled();
    });
  });

  describe("WebSocket URL construction", () => {
    it("constructs the ws URL from projectUrl and channel", () => {
      act(() => {
        inspectorStore.setState((prev) => ({
          ...prev,
          projectUrl: "http://localhost:5005",
        }));
      });

      renderTrackerHook({ enabled: true, channel: "rest" });

      expect(wsCtor).toHaveBeenCalledWith("ws://localhost:5005/webhooks/rest/tracker_stream");
    });

    it("uses wss for https projectUrl", () => {
      act(() => {
        inspectorStore.setState((prev) => ({
          ...prev,
          projectUrl: "https://example.com",
        }));
      });

      renderTrackerHook({ enabled: true, channel: "twilio_media_streams" });

      expect(wsCtor).toHaveBeenCalledWith(
        "wss://example.com/webhooks/twilio_media_streams/tracker_stream",
      );
    });
  });

  describe("onopen", () => {
    it("sends retrieve action when sender query param is present", () => {
      act(() => {
        inspectorStore.setState((prev) => ({
          ...prev,
          projectUrl: "http://localhost:5005",
        }));
      });

      renderTrackerHook({ enabled: true, channel: "rest" }, ["/?sender=existing-sender"]);

      act(() => {
        lastWs?.onopen?.();
      });

      expect(lastWs?.send).toHaveBeenCalledWith(
        JSON.stringify({ action: "retrieve", sender_id: "existing-sender" }),
      );
    });

    it("does not send anything when no sender query param is present", () => {
      act(() => {
        inspectorStore.setState((prev) => ({
          ...prev,
          projectUrl: "http://localhost:5005",
        }));
      });

      renderTrackerHook({ enabled: true, channel: "rest" });

      act(() => {
        lastWs?.onopen?.();
      });

      expect(lastWs?.send).not.toHaveBeenCalled();
    });
  });

  describe("onmessage", () => {
    it("updates the store with sessionId, events, stack and slots on a valid payload", () => {
      act(() => {
        inspectorStore.setState((prev) => ({
          ...prev,
          projectUrl: "http://localhost:5005",
        }));
      });

      renderTrackerHook({ enabled: true, channel: "rest" });

      act(() => {
        lastWs?.onmessage?.({
          data: JSON.stringify({
            sender_id: "abc-123",
            events: [
              {
                event: "slot",
                name: "some_slot",
                value: "some_value",
                timestamp: 1,
              },
            ],
            slots: { some_slot: "some_value" },
            stack: [
              {
                frame_id: "f1",
                flow_id: "my_flow",
                step_id: "s1",
              },
            ],
          }),
        });
      });

      expect(inspectorStore.state.sessionId).toBe("abc-123");
      expect(inspectorStore.state.conversationList).toHaveLength(1);
      expect(inspectorStore.state.conversationList[0].id).toBe("abc-123");
      expect(inspectorStore.state.stack).toEqual([
        {
          frameId: "f1",
          flowId: "my_flow",
          stepId: "s1",
          collect: undefined,
          utter: undefined,
          ended: false,
        },
      ]);
      expect(inspectorStore.state.slots).toEqual({ some_slot: "some_value" });
      expect(inspectorStore.state.inputDisabled).toBe(true);
    });

    it("applies a guided skill and ordered-block stack dump", () => {
      act(() => {
        inspectorStore.setState((prev) => ({
          ...prev,
          projectUrl: "http://localhost:5005",
        }));
      });

      renderTrackerHook({ enabled: true, channel: "rest" });

      act(() => {
        lastWs?.onmessage?.({
          data: JSON.stringify({
            sender_id: "abc-123",
            events: [],
            slots: {},
            stack: [
              { frame_id: "sk", type: "skill", skill_id: "card_replace" },
              {
                frame_id: "blk",
                type: "ordered_block",
                skill_id: "card_replace",
                block_id: "main",
                step_id: "confirm",
              },
            ],
          }),
        });
      });

      expect(inspectorStore.state.sessionId).toBe("abc-123");
      expect(inspectorStore.state.stack).toEqual([
        {
          frameId: "sk",
          flowId: undefined,
          stepId: undefined,
          type: "skill",
          skillId: "card_replace",
          blockId: undefined,
          collect: undefined,
          utter: undefined,
          ended: false,
        },
        {
          frameId: "blk",
          flowId: undefined,
          stepId: "confirm",
          type: "ordered_block",
          skillId: "card_replace",
          blockId: "main",
          collect: undefined,
          utter: undefined,
          ended: false,
        },
      ]);
    });

    it("keeps the previous stack when the new stack is empty", () => {
      const previousStack = [
        {
          frameId: "prev",
          flowId: "prev_flow",
          stepId: "prev_step",
          ended: false,
        },
      ];

      act(() => {
        inspectorStore.setState((prev) => ({
          ...prev,
          projectUrl: "http://localhost:5005",
          stack: previousStack,
        }));
      });

      renderTrackerHook({ enabled: true, channel: "rest" });

      act(() => {
        lastWs?.onmessage?.({
          data: JSON.stringify({
            sender_id: "abc-123",
            events: [],
            slots: {},
            stack: [],
          }),
        });
      });

      expect(inspectorStore.state.stack).toEqual(previousStack);
    });

    it("ignores malformed JSON payloads", () => {
      act(() => {
        inspectorStore.setState((prev) => ({
          ...prev,
          projectUrl: "http://localhost:5005",
        }));
      });

      const initialSessionId = inspectorStore.state.sessionId;
      renderTrackerHook({ enabled: true, channel: "rest" });

      act(() => {
        lastWs?.onmessage?.({ data: "not-json{" });
      });

      expect(inspectorStore.state.sessionId).toBe(initialSessionId);
      expect(mockLogError).toHaveBeenCalled();
    });

    it("ignores payloads that fail schema validation", () => {
      act(() => {
        inspectorStore.setState((prev) => ({
          ...prev,
          projectUrl: "http://localhost:5005",
        }));
      });

      const initialSessionId = inspectorStore.state.sessionId;
      renderTrackerHook({ enabled: true, channel: "rest" });

      act(() => {
        lastWs?.onmessage?.({
          data: JSON.stringify({ totally: "invalid" }),
        });
      });

      expect(inspectorStore.state.sessionId).toBe(initialSessionId);
      expect(mockLogError).toHaveBeenCalled();
    });

    it("keeps the prior stack when a stack frame fails schema validation", () => {
      // Guards fail-closed stack parse after optional Mantle fields (no stack .catch([])).
      const previousStack = [
        {
          frameId: "prev",
          flowId: "prev_flow",
          stepId: "prev_step",
          ended: false,
        },
      ];

      act(() => {
        inspectorStore.setState((prev) => ({
          ...prev,
          projectUrl: "http://localhost:5005",
          sessionId: "sess-before",
          stack: previousStack,
        }));
      });

      renderTrackerHook({ enabled: true, channel: "rest" });

      act(() => {
        lastWs?.onmessage?.({
          data: JSON.stringify({
            sender_id: "should-not-apply",
            events: [{ event: "user", timestamp: 1 }],
            slots: {},
            stack: [{ type: "skill", skill_id: "card_replace" }],
          }),
        });
      });

      expect(inspectorStore.state.sessionId).toBe("sess-before");
      expect(inspectorStore.state.stack).toEqual(previousStack);
    });
  });

  describe("historical compat events pass through unfiltered", () => {
    const dualWrittenPayload = {
      sender_id: "abc-123",
      events: [
        { event: "skill_activated", skill_id: "card_replace", timestamp: 1 },
        { event: "flow_started", flow_id: "card_replace", timestamp: 2 },
        { event: "memory_set", key: "card_replace.reason", value: "lost", timestamp: 3 },
        { event: "slot", name: "card_replace.reason", value: "lost", timestamp: 4 },
        { event: "reset_slots", timestamp: 5 },
        { event: "tool_executed", tool_name: "lock_card", timestamp: 6 },
        { event: "mcp_tool_executed", tool_name: "lock_card", timestamp: 7 },
      ],
      slots: {},
      stack: [],
    };

    function eventTypes() {
      return inspectorStore.state.conversationList[0].events.map((event) =>
        "conversationEventType" in event ? event.conversationEventType : event.__typename,
      );
    }

    // Mantle no longer dual-writes Flow*/SlotSet; trackers persisted before that
    // change still carry them and must render as history rather than be dropped.
    it("keeps historical compat events for a mantle project", () => {
      act(() => {
        inspectorStore.setState((prev) => ({
          ...prev,
          projectUrl: "http://localhost:5005",
          engineType: "mantle",
        }));
      });

      renderTrackerHook({ enabled: true, channel: "rest" });

      act(() => {
        lastWs?.onmessage?.({ data: JSON.stringify(dualWrittenPayload) });
      });

      expect(eventTypes()).toEqual([
        "SKILL_ACTIVATED",
        "FLOW_STARTED",
        "MEMORY_SET",
        "SLOT",
        "RESET_SLOTS",
        "TOOL_EXECUTED",
        "MCP_TOOL_EXECUTED",
      ]);
      const slotRelated = inspectorStore.state.slotRelatedEvents.map(
        (event) => event.conversationEventType,
      );
      expect(slotRelated).toContain("MEMORY_SET");
      expect(slotRelated).toContain("SLOT");
    });

    it("dual-reads ProtoJSON envelopes mixed with classic flat events", () => {
      act(() => {
        inspectorStore.setState((prev) => ({
          ...prev,
          projectUrl: "http://localhost:5005",
          engineType: "mantle",
        }));
      });

      renderTrackerHook({ enabled: true, channel: "rest" });

      act(() => {
        lastWs?.onmessage?.({
          data: JSON.stringify({
            sender_id: "abc-123",
            events: [
              {
                conversation_id: "abc-123",
                timestamp: 1,
                user: { text: "hi", parse_data: {} },
              },
              { event: "bot", text: "hello", timestamp: 2 },
              { conversation_id: "abc-123" },
              {
                conversation_id: "abc-123",
                timestamp: 3,
                memory_set: { key: "amount", value_json: "42" },
              },
              { event: "slot", name: "amount", value: 42, timestamp: 4 },
            ],
            slots: {},
            stack: [],
          }),
        });
      });

      const events = inspectorStore.state.conversationList[0].events;
      expect(events.map((event) => ("text" in event ? event.text : event.name))).toEqual([
        "hi",
        "hello",
        "amount",
        "amount",
      ]);
      expect(events[2]).toMatchObject({ conversationEventType: "MEMORY_SET", value: 42 });
      expect(events[3]).toMatchObject({ conversationEventType: "SLOT" });
      expect(mockLogError).toHaveBeenCalledWith(
        expect.objectContaining({ message: "Dropped invalid ProtoJSON tracker event" }),
        expect.objectContaining({
          tags: {
            component: "useTrackerConnection",
            action: "normalizeTrackerPayload",
          },
        }),
      );
    });

    it("leaves a CALM v1 payload untouched", () => {
      act(() => {
        inspectorStore.setState((prev) => ({
          ...prev,
          projectUrl: "http://localhost:5005",
          engineType: "calm",
        }));
      });

      renderTrackerHook({ enabled: true, channel: "rest" });

      act(() => {
        lastWs?.onmessage?.({ data: JSON.stringify(dualWrittenPayload) });
      });

      expect(eventTypes()).toEqual([
        "SKILL_ACTIVATED",
        "FLOW_STARTED",
        "MEMORY_SET",
        "SLOT",
        "RESET_SLOTS",
        "TOOL_EXECUTED",
        "MCP_TOOL_EXECUTED",
      ]);
    });
  });

  describe("sender URL param sync", () => {
    it("locks the sender query param to the first sender_id seen when URL is empty", () => {
      act(() => {
        inspectorStore.setState((prev) => ({
          ...prev,
          projectUrl: "http://localhost:5005",
        }));
      });

      const { capturedSearch } = renderWithSearchParamsProbe(["/"]);

      act(() => {
        lastWs?.onmessage?.({
          data: JSON.stringify({
            sender_id: "first-sender",
            events: [],
            slots: {},
            stack: [],
          }),
        });
      });

      expect(capturedSearch.current).toBe("first-sender");
    });

    it("keeps the locked sender_id when a message arrives for a different sender_id", () => {
      act(() => {
        inspectorStore.setState((prev) => ({
          ...prev,
          projectUrl: "http://localhost:5005",
        }));
      });

      const { capturedSearch } = renderWithSearchParamsProbe(["/?sender=locked-sender"]);

      act(() => {
        lastWs?.onmessage?.({
          data: JSON.stringify({
            sender_id: "other-sender",
            events: [],
            slots: {},
            stack: [],
          }),
        });
      });

      expect(capturedSearch.current).toBe("locked-sender");
    });
  });

  describe("conversation isolation", () => {
    it("does not update the store when a message arrives for a different sender_id", () => {
      act(() => {
        inspectorStore.setState((prev) => ({
          ...prev,
          projectUrl: "http://localhost:5005",
          sessionId: "locked-sender",
        }));
      });

      renderTrackerHook({ enabled: true, channel: "rest" }, ["/?sender=locked-sender"]);

      act(() => {
        lastWs?.onmessage?.({
          data: JSON.stringify({
            sender_id: "other-sender",
            events: [
              {
                event: "slot",
                name: "some_slot",
                value: "some_value",
                timestamp: 1,
              },
            ],
            slots: {},
            stack: [
              {
                frame_id: "f1",
                flow_id: "my_flow",
                step_id: "s1",
              },
            ],
          }),
        });
      });

      expect(inspectorStore.state.sessionId).toBe("locked-sender");
      expect(inspectorStore.state.conversationList).toHaveLength(0);
      expect(inspectorStore.state.stack).toEqual([]);
      expect(inspectorStore.state.slots).toEqual({});
    });

    it("locks to the first sender synchronously so rapid second message with another sender is ignored", () => {
      act(() => {
        inspectorStore.setState((prev) => ({
          ...prev,
          projectUrl: "http://localhost:5005",
        }));
      });

      renderTrackerHook({ enabled: true, channel: "rest" });

      // Two messages in the same tick — the first locks the sender, the
      // second must not be able to override before React re-renders.
      act(() => {
        lastWs?.onmessage?.({
          data: JSON.stringify({
            sender_id: "first-sender",
            events: [],
            slots: {},
            stack: [],
          }),
        });
        lastWs?.onmessage?.({
          data: JSON.stringify({
            sender_id: "second-sender",
            events: [],
            slots: {},
            stack: [],
          }),
        });
      });

      expect(inspectorStore.state.sessionId).toBe("first-sender");
      expect(inspectorStore.state.conversationList).toHaveLength(1);
      expect(inspectorStore.state.conversationList[0].id).toBe("first-sender");
    });
  });

  describe("WebSocket lifecycle", () => {
    it("does not recreate the WebSocket when the sender URL param changes", () => {
      act(() => {
        inspectorStore.setState((prev) => ({
          ...prev,
          projectUrl: "http://localhost:5005",
        }));
      });

      renderTrackerHook({ enabled: true, channel: "rest" }, ["/"]);

      expect(wsCtor).toHaveBeenCalledTimes(1);

      // First message locks the URL to "first-sender". The WS must NOT be
      // torn down and rebuilt as a result of that URL change.
      act(() => {
        lastWs?.onmessage?.({
          data: JSON.stringify({
            sender_id: "first-sender",
            events: [],
            slots: {},
            stack: [],
          }),
        });
      });

      expect(wsCtor).toHaveBeenCalledTimes(1);
    });
  });

  describe("cleanup", () => {
    it("closes the WebSocket when the hook unmounts", () => {
      act(() => {
        inspectorStore.setState((prev) => ({
          ...prev,
          projectUrl: "http://localhost:5005",
        }));
      });

      const { unmount } = renderTrackerHook({
        enabled: true,
        channel: "rest",
      });

      const ws = lastWs;
      expect(ws?.close).not.toHaveBeenCalled();

      unmount();

      expect(ws?.close).toHaveBeenCalled();
    });
  });
});
